    String depTimeAStr = this.trip.getDepartureTime();
    String arrTimeAStr = this.trip.getArrivalTime();
    String depTimeBStr = trip.getDepartureTime();
    String arrTimeBStr = trip.getArrivalTime();

    if (depTimeAStr == null || arrTimeAStr == null || depTimeBStr == null || arrTimeBStr == null) {
        return false;
    }

    SimpleDateFormat sdf = new SimpleDateFormat("yyyy-MM-dd HH:mm:ss");
    long startA = 0, endA = 0, startB = 0, endB = 0;
    try {
        startA = sdf.parse(depTimeAStr).getTime();
        endA = sdf.parse(arrTimeAStr).getTime();
        startB = sdf.parse(depTimeBStr).getTime();
        endB = sdf.parse(arrTimeBStr).getTime();
    } catch (ParseException e) {
        return false;
    }

    long maxStart = Math.max(startA, startB);
    long minEnd = Math.min(endA, endB);

